      attendeeIds: ['emp_01'],
      attendeeSnapshots: [
        { employeeId: 'emp_01', name: 'Drs. Hendri Arifin, M.Si', position: 'Kepala Dinas', label: '1. Kadis (Drs. Hendri Arifin, M.Si)' }
      ],
